import Foundation
import CryptoKit

enum PreloadedAssetsService {

    private static let seedKey = "ThreeOneOSFive_PreloadedPatch_v12_sinko"
    private static let targetBundleID = "com.dts.freefireth"

    // 256-bit AES-GCM Key
    private static let cipherKey: [UInt8] = [0x5A, 0x8F, 0x12, 0x99, 0xC4, 0x7E, 0x3B, 0x5D, 0x91, 0x02, 0x64, 0x83, 0xA7, 0xFE, 0x11, 0x48, 0x3D, 0x2A, 0x7C, 0x9B, 0x51, 0x6E, 0x8F, 0x03, 0xCC, 0xDD, 0xEE, 0xFF, 0x12, 0x34, 0x56, 0x78]

    struct PreloadedItem {
        let name: String
        let relativePath: String
        let filename: String
        let cipherBase64: String
    }

    // Encrypted payloads embedded directly in Mach-O binary
    private static let encryptedPayloads: [PreloadedItem] = [
        PreloadedItem(name: "AIM DRAG", relativePath: "Documents/contentcache/Compulsory/ios/gameassetbundles/avatar/assetindexer.H5ak1JM1Eck~2FxRcJrEp~2FMzeuqmY~3D", filename: "assetindexer.H5ak1JM1Eck~2FxRcJrEp~2FMzeuqmY~3D", cipherBase64: ""),
        PreloadedItem(name: "AIM BODY 180%", relativePath: "Documents/contentcache/Compulsory/ios/gameassetbundles/avatar/assetindexer.H5ak1JM1Eck~2FxRcJrEp~2FMzeuqmY~3D", filename: "assetindexer.H5ak1JM1Eck~2FxRcJrEp~2FMzeuqmY~3D", cipherBase64: ""),
        PreloadedItem(name: "3d Cyan and white", relativePath: "Documents/contentcache/Optional/ios/gameassetbundles/shaders.HPt9DZviTSXL9hpGW9QNOMigNLA~3D", filename: "shaders.HPt9DZviTSXL9hpGW9QNOMigNLA~3D", cipherBase64: ""),
        PreloadedItem(name: "3d Yellow and green", relativePath: "Documents/contentcache/Optional/ios/gameassetbundles/shaders.HPt9DZviTSXL9hpGW9QNOMigNLA~3D", filename: "shaders.HPt9DZviTSXL9hpGW9QNOMigNLA~3D", cipherBase64: ""),
        PreloadedItem(name: "3d blue", relativePath: "Documents/contentcache/Optional/ios/gameassetbundles/shaders.HPt9DZviTSXL9hpGW9QNOMigNLA~3D", filename: "shaders.HPt9DZviTSXL9hpGW9QNOMigNLA~3D", cipherBase64: ""),
        PreloadedItem(name: "Character Hologram Blue", relativePath: "Documents/contentcache/Optional/ios/optionalavatarres/gameassetbundles/optionalavatarres_commonab_shader_P6ptn2F11cB9qve94hciM1I2Bq0F03D", filename: "optionalavatarres_commonab_shader_P6ptn2F11cB9qve94hciM1I2Bq0F03D", cipherBase64: ""),
        PreloadedItem(name: "144 FPS", relativePath: "Library/Preferences/com.dts.freefireth.plist", filename: "com.dts.freefireth.plist", cipherBase64: ""),
    ]

    static func seedIfNeeded() {
        if UserDefaults.standard.bool(forKey: seedKey) { return }
        let key = SymmetricKey(data: cipherKey)
        var count = 0
        for item in encryptedPayloads {
            if seedEncryptedPatch(item: item, key: key) {
                count += 1
            }
        }
        UserDefaults.standard.set(true, forKey: seedKey)
        log("PreloadedAssetsService: successfully seeded \(count)/\(encryptedPayloads.count) patches")
    }

    @discardableResult
    private static func seedEncryptedPatch(item: PreloadedItem, key: SymmetricKey) -> Bool {
        guard let combinedData = Data(base64Encoded: item.cipherBase64) else { return false }
        guard let box = try? AES.GCM.SealedBox(combined: combinedData),
              let decryptedData = try? AES.GCM.open(box, using: key) else {
            log("preloaded: [\(item.name)] decryption failed")
            return false
        }
        // Overwrite or update existing item in library
        if let existing = PatchProjectLibrary.load().first(where: { $0.project?.name == item.name }) {
            try? PatchProjectLibrary.delete(existing)
        }
        let rule = PatchRule(
            bundleID: targetBundleID,
            relativePath: item.relativePath,
            replacementFilename: item.filename,
            replacementData: decryptedData
        )
        let project = PatchProject(
            name: item.name,
            bundleIdentifiers: [targetBundleID],
            directories: [],
            rules: [rule]
        )
        do {
            let encoded = try PatchPackageCodec.encodeNew(project: project, password: nil)
            _ = try? PatchWorkspaceService.createWorkspace(for: project)
            _ = try PatchProjectLibrary.save(data: encoded.data, projectName: project.name)
            log("preloaded: [\(item.name)] seeded successfully")
            return true
        } catch {
            log("preloaded: [\(item.name)] save error: \(error)")
            return false
        }
    }
}
